/** Styles for the article social share bar. **/
.article-header-row {
  .share-wrapper {
    display: flex;
    flex-direction: row;
    justify-items: flex-end;
    justify-content: flex-end;
    padding-bottom: $gutter;
    border-bottom: 2px solid $gray-20;
    padding-top: calc($gutter * .75);

    .flag-bookmark,
    .article-bookmark {
      @include breakpoint($bp-small max-width) {
        margin: calc($gutter/2);
      }
      a {
        text-decoration: none;
        &:focus-visible {
          .icon.bookmark {
            outline: 2px solid $tab-focus-blue;
            &:before {
              outline: 0;
            }
          }
        }
        &.flag-login {
          text-decoration: none;
        }
      }
    }

    .ajax-progress {
      display: none;
    }

    .icon {
      &.bookmark {
        @include ama-button("small", "actions", "../icons/svg/social-share-icons/v1-icon-save-selected.svg");
        &:before {
          height: 24px;
          width: 16px;
        }
      }
    }

    .action-flag {
      .icon {
        &.bookmark {
          &:before {
            background-image: url("../icons/svg/social-share-icons/v1-icon-save-not-selected.svg");
          }
        }
      }
    }

    //  Icon and print icon parent styles.
    .icon {
      a {
        &:hover {
          text-decoration: none;
        }
      }
      &.copy {
        @include ama-button("small", "actions", "../icons/svg/social-share-icons/v1-icon-copy-not-selected.svg");
        &:before {
          height: 24px;
          width: 22px;
          top: -5px;
        }
        &:hover {
          cursor: pointer;
        }
        &.copied,
        &.copied:hover {
          &:before {
            background-image: url("../icons/svg/social-share-icons/v1-icon-copy-selected.svg");
          }
        }
      }
      &.print {
        @include ama-button("small", "actions", "../icons/svg/social-share-icons/v1-icon-print-not-selected.svg");
        &:before {
          height: 18px;
          width: 21px;
        }
        &:hover {
          cursor: pointer;
          &:before {
            background-image: url("../icons/svg/social-share-icons/v1-icon-print-not-selected.svg");
          }
        }
      }
      &.printed {
        &:before {
          background-image: url("../icons/svg/social-share-icons/v1-icon-print-selected.svg");
        }
      }
      &.share {
        @include ama-button("small", "actions", "../icons/svg/social-share-icons/v1-icon-share-not-selected.svg");
        &:before {
          width: 21px;
          height: 17.25px;
        }
        &.shared {
          &:before {
            background-image: url("../icons/svg/social-share-icons/v1-icon-share-selected.svg");
          }
        }
        &:hover {
          cursor: pointer;
        }

        //  Social Modal.
        .share-modal {
          display:flex;
          flex-direction: column;
          border: 1px solid $gray-4;
          z-index: 99;
          bottom: 0;
          right: 0;
          position: fixed;
          padding: 7px;
          background: $white;
          display: block;
          border-radius: 10px;
          width: 221px;
          :after {
            content: "";
            display: inline-block;
            width: 100%;
          }
          @include breakpoint($bp-small) {
            position: absolute;
            right: -130px;
            bottom: -244px;
          }
          &.hidden {
            display: none;
            .click-catcher {
              display:none;
            }
          }
          .click-catcher {
            z-index: 0;
            position: fixed;
            cursor: default;
            top: 0;
            right: 0;
            left: 0;
            bottom: 0;
            display: block;
            background: transparent;
          }
          a {
            white-space: nowrap;
            display: block;
            position:relative;
            font-size: 16px;
            font-weight: $font-weight-regular;
            text-decoration: none;
            border-radius: 4px;
            &:focus {
              text-decoration: underline;
            }
            &:hover {
              background-color: $gray-4;
            }
            &:last-child {
              padding-bottom: 0;
            }
            &:before {
              width: 24px;
              height: 24px;
              left: 7px;
              top: 10px;
              content: " ";
              background-repeat: no-repeat;
              position: absolute;
            }
          }
          .facebook {
            &:before {
              background-image: url("../icons/svg/social-share-icons/v1-icon-share-facebook.svg");
            }
          }
          .linkedin {
            &:before {
              background-image: url("../icons/svg/social-share-icons/v1-icon-share-linkedin.svg");
            }
          }
          .twitter {
            &:before {
              background-image: url("../icons/svg/social-share-icons/v1-icon-share-twitter.svg");
            }
          }
          .email {
            &:before {
              background-image: url("../icons/svg/social-share-icons/v1-icon-share-email.svg");
            }
          }
          .doximity {
            &:before {
              background-image: url("../icons/svg/social-share-icons/v1-icon-share-doximity.svg");
            }
          }
        }
      }
    }
    .icon.print {
      background-color: #fff;
    }
    .contextual-link-wrapper {
      position: absolute;
      display: none;
      left: 0;
      @include breakpoint($bp-small max-width) {
        display: block;
      }
      &:hover, &:active {
        text-decoration: underline;
        color: $homepagePurple;
      }
      a {
        color: black;
        font-size: 20px;
        text-decoration: underline;
        text-transform: none;
        padding: 0;
        &:focus-visible {
          outline: 2px solid $tab-focus-blue;
        }
      }
    }
    .print-pdf {
      text-decoration: none;
      &:focus-visible {
        .icon.print {
          outline: 2px solid $tab-focus-blue;
        }
      }
    }
  }
}

//  Styles for the social share bar in the news article masthead.
.article-header {
  z-index: 99;
  position: relative;
  .share-row {
    .share {
      @include breakpoint($bp-small) {
        height: 36px;
      }
      &.is-sticky {
        .share-wrapper {
          display: flex;
          flex-direction: column;
          justify-content: space-around;
          align-items: center;
          top: 0;
          left: 0;
          position: absolute;
          margin-top: 250px;
          width: 50px !important;

          .share-modal {
            right: -229px;
            bottom: -193px;
          }
        }
      }
      .share-wrapper {
        border-bottom: 0;
        padding-top: 0;
        padding-bottom: 0;
        &.share-wrapper--fixed {
          top: 0;
          left: 0;
          position: absolute;
          margin-top: 250px;
          .icon {
            padding: 0;
            width: 44px;
            height: 44px;
            .text {
              display: none;
            }
            &::before {
              margin: 0 auto;
            }
          }
          // Adjust icon alignment when sticky/scrolling
          .icon {
            margin: 0 0 15px 0;
            padding-left: 0;
            border-radius: 100px;
          }
        }
        @include breakpoint($bp-small max-width) {
          display: flex;
          position: fixed;
          align-items: center;
          z-index: 99;
          bottom: 0;
          right: 0;
          left: 0;
          margin: calc($gutter/4) 0 0;
          background-color: $white;
          border-top: 1px solid $bg-purple;
          padding: 0;
          box-shadow: 0px 4px 20px -4px rgba(23, 24, 24, 0.12);
          .icon.masthead {
            padding: 0;
            width: 44px;
            height: 44px;
            margin: calc($gutter/2) calc($gutter/2) calc($gutter/2) 0;
            &.bookmark {
              margin: 0;
            }
            .text {
              display: none;
            }
            &::before {
              margin: 0 auto;
            }
          }
        }
        .icon {
          //@include ama-button("small", "actions");
          &.share,
          &.copy {
            &:focus-visible {
              background-color: $white;
              outline: 2px solid $tab-focus-blue;

              .share-modal {
                display: flex;

                &:focus-within {
                  display: flex;
                }
              }
            }
            &:focus-within {
              .share-modal {
                display: flex;
              }
            }
          }
          &.shared,
          &.printed,
          &.copied {
            background-color: $gray-4;
          }
        }
        .action-unflag {
          .icon {
            &.bookmark {
              background-color: $gray-4;
            }
          }
        }
        div.icon.print {
          @include breakpoint($bp-small max-width) {
            display: none;
          }
        }

        .share-modal {
          cursor: default;
          background: $white;
          border-radius: 8px;
          border: 1px solid $gray-4;
          box-shadow: 0px 8px 20px -4px rgba(23, 24, 24, 0.12);
          @include breakpoint($bp-small max-width) {
            bottom: 87px;
            right: 14px;
          }

          a {
            display: block;
            height: 44px;
            align-items: center;
            padding-bottom: 0;
            text-indent: 37px;
            line-height: 44px;
            &:focus-visible {
              outline: 2px solid $tab-focus-blue;
            }
          }
        }

        .article-bookmark {
          @include breakpoint($bp-small max-width) {
            height: 40px;
          }
        }
      }
    }
  }
}
